tool_trajectory.result:
{
  "id": 1,
  "knowledge": "Atmospheric Observability Index (AOI)",
  "description": "Quantifies how conducive atmospheric conditions are for signal detection.",
  "definition": "$\\text{AOI} = \\text{AtmosTransparency} \\times (1 - \\frac{\\text{HumidityRate}}{100}) \\times (1 - 0.02 \\times \\text{WindSpeedMs})$, where values closer to 1 indicate ideal observation conditions."
}

args.sql:
WITH scored AS (
 SELECT *, atmostransparency * (1 - humidityrate / 100.0) * (1 - 0.02 * windspeedms) AS aoi
 FROM observatories
), classified AS (
 SELECT *, COALESCE(aoi > 0.85 AND lunarstage IN ('New', 'First Quarter') AND lunardistdeg > 45 AND solarstatus IN ('Low', 'Moderate'), FALSE) AS meets_good_observation_conditions
 FROM scored
)
SELECT meets_good_observation_conditions, COUNT(*) AS station_count, AVG(aoi) AS average_aoi
FROM classified
GROUP BY meets_good_observation_conditions;

